static void mochColor(LinkedList<Objeto>L1,
                      LinkedList<Objeto>L2,
                      int max,String c,int i){

    if(peso(L1)>max)return;

    if(!L1.isEmpty())
        System.out.println(L1);

    for(int k=i;k<L2.size();k++){

        Objeto x=L2.get(k);

        if(x.color.equals(c)){
            L1.add(x);
            mochColor(L1,L2,max,c,k+1);
            L1.removeLast();
        }
    }
}
